def sortByFrequency(nums):
    count = {}
    for x in nums:
        count[x] = count.get(x, 0) + 1
    buckets = [[] for _ in range(len(nums) + 1)]
    for x, c in count.items():
        buckets[c].append(x)
    out = []
    for c in range(1, len(nums) + 1):
        for x in sorted(buckets[c], reverse=True):
            out.extend([x] * c)
    return out
